package ug.audiocity.studio;
import java.io.*;import java.nio.*;import java.nio.file.*;
public final class PhonePresetTests {
 static int passed;static void check(boolean c,String m){if(!c)throw new AssertionError(m);passed++;}
 static Core.Source read(String path)throws Exception{FloatBuffer b=ByteBuffer.wrap(Files.readAllBytes(Paths.get(path))).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();float[] a=new float[b.remaining()];b.get(a);return new Core.Memory(a);}
 static double energy(Core.Source s,Core.Fx f){Core.Processor p=new Core.Processor();p.configure(f,100);float[] data=new float[1024];double energy=0;for(int at=0;at<s.frames();at+=512){int n=Math.min(512,s.frames()-at);for(int i=0;i<n;i++){data[i*2]=s.sample(at+i,0);data[i*2+1]=s.sample(at+i,1);}p.apply(data,n);for(int i=0;i<n*2;i++)energy+=data[i]*data[i];}return energy/(s.frames()*2);}
 public static void main(String[] args)throws Exception{
  Core.Biquad hp=new Core.Biquad();hp.set(3,90,0);check(hp.db(30)<-18&&Math.abs(hp.db(90)+3.01)<.1&&hp.db(250)>-.2,"Low cut removes rumble while preserving the measured vocal body");Core.Biquad bell=new Core.Biquad();bell.set(1,650,-3);check(Math.abs(bell.db(650)+3)<.01&&bell.db(5000)>-.2,"Mid bell follows its adjustable frequency");
  Core.Fx copied=PhoneVocalPresets.profile(1).copy();check(copied.hpf&&copied.peakGuard&&copied.midHz==650&&copied.gateFloor==.4,"Phone filter and expander settings survive copies");
  for(int index=0;index<4;index++){Core.Fx profile=PhoneVocalPresets.profile(index);check(profile.hpf&&profile.comp&&profile.deess&&!profile.sat,"All phone profiles use controlled dynamics without added drive");Core.Source tone=new Core.Memory(StudioTests.wave(Core.RATE*2,250,.2));PhoneVocalPresets.Result r=PhoneVocalPresets.calibrate(tone,index,100);check(!r.fx.gate&&Double.isFinite(r.fx.outputDb),"Continuous vocals calibrate without inventing a noise-only pause");}
  for(String path:args){Core.Source source=read(path);for(int index=0;index<4;index++){PhoneVocalPresets.Result r=PhoneVocalPresets.calibrate(source,index,100);check(r.activeDb>-25&&r.activeDb< -8&&r.fx.inputDb<=0,"Measured supplied takes are reduced into the intended input range");Core.Processor p=new Core.Processor();p.configure(r.fx,100);float[] data=new float[1024];double peak=0;boolean finite=true;for(int at=0;at<source.frames();at+=512){int n=Math.min(512,source.frames()-at);for(int i=0;i<n;i++){data[i*2]=source.sample(at+i,0);data[i*2+1]=source.sample(at+i,1);}p.apply(data,n);for(int i=0;i<n*2;i++){peak=Math.max(peak,Math.abs(data[i]));finite&=Float.isFinite(data[i]);}}check(finite&&peak<.88,"Calibrated supplied vocal retains headroom and finite samples");double change=10*Math.log10(energy(source,r.fx)/energy(source,new Core.Fx()));check(Math.abs(change)<3,"Preset levels stay close to source, subject to peak protection");System.out.println("Phone preset "+index+" input "+r.fx.inputDb+" dB, output "+r.fx.outputDb+" dB, source-relative RMS "+change+" dB");}}
  File dir=Files.createTempDirectory("phone-preset-json").toFile();Core.Session session=new Core.Session();session.directory=dir.getPath();Core.Track track=new Core.Track("Phone vocal",0);track.fx=PhoneVocalPresets.profile(2);track.fx.inputDb=-2.5;track.fx.outputDb=3.2;session.tracks.add(track);AudioIO.save(session);Core.Fx saved=AudioIO.load(dir).tracks.get(0).fx;check(saved.hpf&&saved.peakGuard&&saved.highPassHz==95&&saved.midHz==700&&saved.inputDb==-2.5&&saved.outputDb==3.2&&saved.gateFloor==.4,"All new phone controls save and reload");for(File f:dir.listFiles())f.delete();dir.delete();System.out.println(passed+" phone-preset checks passed.");
 }
}
